function resizeCanvas(delta){const canvas=document.querySelector('#component-canvas'),current=parseInt(canvas.dataset.size||localStorage.getItem('automation-canvas-size')||'1400',10),next=Math.max(500,current+delta);canvas.dataset.size=next;canvas.style.width=next+'px';canvas.style.height=next+'px';localStorage.setItem('automation-canvas-size',next);updateCanvasSize();drawConnections()}
function updateCanvasSize(){const canvas=document.querySelector('#component-canvas'),label=document.querySelector('#canvas-size'),size=parseInt(canvas.dataset.size||'1400',10);if(label)label.textContent='Width: '+size+' px\nHeight: '+size+' px'}
function showDetails(details){const dialog=document.querySelector('#details-dialog'),content=document.querySelector('#details-content'),form=document.createElement('form');content.replaceChildren();dialog.dataset.componentId=details.id;dialog.dataset.fritz=String(!!details.fritzDevice);form.onsubmit=event=>saveDetails(event,details.id);form.append(field('Name','details-name','text',details.name||''));if(details.booleanDelay)form.append(delayField('On-delay','details-on-delay',details.onDelayMillis),delayField('Off-delay','details-off-delay',details.offDelayMillis));if(details.booleanPulse)form.append(delayField('Pulse duration','details-pulse-duration',details.pulseMillis));if(details.numericOperation){const output=deviceSelect('Output type','details-output-type',[['Float','float'],['Integer (rounded)','integer']]);output.querySelector('select').value=details.outputType;form.append(output)}if(details.counter){const output=deviceSelect('Output type','details-output-type',[['Float','float'],['Integer (rounded)','integer']]),persistence=field('Persist counter value','details-counter-persistence','checkbox');output.querySelector('select').value=details.outputType;persistence.querySelector('input').checked=details.persistenceEnabled;form.append(field('Step size','details-counter-step','number',details.stepSize),output,persistence);const value=document.createElement('p');value.textContent='Counter value: '+details.counterValue;form.append(value)}if(details.booleanValueConverter){const output=deviceSelect('Output type','details-output-type',[['Integer','integer'],['Float','float'],['String','string']]);output.querySelector('select').value=details.outputType;const numeric=details.outputType!=='string';form.append(output,field('Value when true','details-true-value',numeric?'number':'text',details.trueValue),field('Value when false','details-false-value',numeric?'number':'text',details.falseValue))}if(details.integerBooleanConverter){const comparison=deviceSelect('Comparison','details-comparison',[['Greater than or equal','greaterOrEqual'],['Smaller than or equal','lessOrEqual'],['Equal to value','equal']]);comparison.querySelector('select').value=details.comparison;form.append(comparison,field('Limit / value','details-comparison-value','number',details.comparisonValue))}if(details.databaseDataSink){const table=document.createElement('p');table.textContent='Table: '+details.table;form.append(table);renderCronEditor(form);setCronEditor(details.cron,details.schedulerEnabled);const last=document.createElement('p'),strong=document.createElement('strong');strong.textContent='Last write: ';last.append(strong,document.createTextNode(details.lastWriteDetails));form.append(last)}const metadata=[['ID',details.id],['Class',details.className]];if(details.fritzDevice)metadata.push(['FRITZ! device name',details.fritzDeviceName||'Unavailable'],['FRITZ! product name',details.fritzProductName||'Unavailable'],['FRITZ! identifier',details.fritzIdentifier||'Unavailable']);metadata.push(['Valid',details.valid?'Yes':'No'],['Status',details.status||'—'],['Help',details.help||'—'],['Outputs',details.outputCount??'—']);metadata.forEach(([label,value])=>{const row=document.createElement('p'),strong=document.createElement('strong');strong.textContent=label+': ';row.append(strong,document.createTextNode(String(value)));form.append(row)});if(details.inputs&&details.inputs.length){const h=document.createElement('h3');h.textContent='Inputs';form.append(h);details.inputs.forEach((input,index)=>{const p=document.createElement('p');p.textContent=index+': '+input.name+' ('+input.type+') — '+(input.used?'connected':'free');form.append(p)})}const actions=document.createElement('div'),save=document.createElement('button');actions.className='dialog-actions';save.type='submit';save.textContent='Save';actions.append(save);form.append(actions);content.append(form);dialog.showModal()}
function updateFritzDetailValues(details){[['FRITZ! device name',details.fritzDeviceName],['FRITZ! product name',details.fritzProductName],['FRITZ! identifier',details.fritzIdentifier]].forEach(([label,value])=>{const row=[...document.querySelectorAll('#details-content p')].find(item=>item.querySelector('strong')?.textContent===label+': ');if(row&&row.lastChild)row.lastChild.nodeValue=String(value||'Unavailable')})}
function saveDetails(event,id){event.preventDefault();const request={id:Number(id),name:document.querySelector('#details-name').value};const on=document.querySelector('#details-on-delay'),off=document.querySelector('#details-off-delay');if(on){request.onDelayMillis=Number(on.value)*Number(document.querySelector('#details-on-delay-unit').value);request.offDelayMillis=Number(off.value)*Number(document.querySelector('#details-off-delay-unit').value);if(!Number.isFinite(request.onDelayMillis)||request.onDelayMillis<0||!Number.isFinite(request.offDelayMillis)||request.offDelayMillis<0){showToast('Delay values must be non-negative numbers',true);return}request.onDelayMillis=Math.round(request.onDelayMillis);request.offDelayMillis=Math.round(request.offDelayMillis)}const pulse=document.querySelector('#details-pulse-duration');if(pulse){request.pulseMillis=Math.round(Number(pulse.value)*Number(document.querySelector('#details-pulse-duration-unit').value));if(!Number.isFinite(request.pulseMillis)||request.pulseMillis<=0){showToast('Pulse duration must be greater than zero',true);return}}const output=document.querySelector('#details-output-type');if(output){request.outputType=output.value;const trueValue=document.querySelector('#details-true-value'),falseValue=document.querySelector('#details-false-value');if(trueValue){request.trueValue=trueValue.value;request.falseValue=falseValue.value}}const counterStep=document.querySelector('#details-counter-step');if(counterStep){request.stepSize=Number(counterStep.value);request.persistenceEnabled=document.querySelector('#details-counter-persistence').checked;if(!Number.isFinite(request.stepSize)||request.stepSize<=0){showToast('Step size must be greater than zero',true);return}}if(document.querySelector('#details-comparison')){request.comparison=document.querySelector('#details-comparison').value;request.comparisonValue=Number(document.querySelector('#details-comparison-value').value);if(!Number.isSafeInteger(request.comparisonValue)){showToast('Limit / value must be an integer',true);return}}if(document.querySelector('#database-scheduler-enabled')){request.schedulerEnabled=document.querySelector('#database-scheduler-enabled').checked;request.cron=cronExpression()}Object.assign(request,additionalDetailRequest());send('updateDetails:'+JSON.stringify(request));document.querySelector('#details-dialog').close()}

const showDetailsBase=showDetails;
showDetails=function(details){showDetailsBase(details);const form=document.querySelector('#details-content form'),actions=form?.querySelector('.dialog-actions');if(!form||!actions)return;if(details.fixedNumericValue){const type=deviceSelect('Value type','details-fixed-type',[['Integer','integer'],['Float','float']]);type.querySelector('select').value=details.valueType;const value=field('Value','details-fixed-value','number',details.fixedValue);value.querySelector('input').step=details.valueType==='integer'?'1':'any';type.querySelector('select').onchange=()=>value.querySelector('input').step=type.querySelector('select').value==='integer'?'1':'any';form.insertBefore(type,actions);form.insertBefore(value,actions)}if(details.fritzConverter){const type=deviceSelect('FRITZ! converter','details-fritz-converter',[['Number','number'],['Boolean','boolean'],['String','string']]);type.querySelector('select').value=details.converterType;const settings=document.createElement('div');settings.id='details-fritz-converter-settings';const render=()=>{settings.replaceChildren();if(type.querySelector('select').value==='number')settings.append(field('Scale before','details-scale-before','number',details.scaleFactorBefore??1),field('Offset before','details-offset-before','number',details.offsetBefore??0),field('Scale after','details-scale-after','number',details.scaleFactorAfter??1),field('Offset after','details-offset-after','number',details.offsetAfter??0));else if(type.querySelector('select').value==='boolean'){settings.append(field('Decision limit','details-decision-limit','number',details.decisionLimit??1));const decision=deviceSelect('Decision','details-decision-type',[['More or equal',1],['More',2],['Less or equal',3],['Less',4]]);decision.querySelector('select').value=details.decisionType??1;settings.append(decision)}};type.querySelector('select').onchange=render;render();form.insertBefore(type,actions);form.insertBefore(settings,actions)}}
function additionalDetailRequest(){const request={},fixed=document.querySelector('#details-fixed-value'),converter=document.querySelector('#details-fritz-converter');if(fixed){request.valueType=document.querySelector('#details-fixed-type').value;request.fixedValue=fixed.value}if(converter){request.converter=converter.value;if(converter.value==='number'){request.scaleFactorBefore=num('details-scale-before',1);request.offsetBefore=num('details-offset-before',0);request.scaleFactorAfter=num('details-scale-after',1);request.offsetAfter=num('details-offset-after',0)}else if(converter.value==='boolean'){request.decisionLimit=num('details-decision-limit',1);request.decisionType=num('details-decision-type',1)}}return request}

function handleAuthState(state,users){authState=state;if(Array.isArray(users))managedUsers=users;document.body.classList.toggle('view-only',!state.canWrite);const label=document.querySelector('#auth-state'),button=document.querySelector('#auth-button'),admin=document.querySelector('#user-admin-button'),authDialog=document.querySelector('#auth-dialog');label.textContent=!state.enabled?'Access control off':state.authenticated?state.username+(state.canWrite?' · write':' · view only'):state.anonymousView?'Anonymous view':'Login required';button.hidden=!state.enabled;button.textContent=state.authenticated?'Logout':'Login';button.onclick=state.authenticated?logout:openAuthDialog;admin.hidden=!state.admin;if(state.authenticated&&authDialog.open)authDialog.close();if(state.canView&&!automationStarted){automationStarted=true;init_objects();startLiveUpdates()}if(!state.canView){automationStarted=false;clearInterval(timer);cards.clear();document.querySelector('#component-canvas').querySelectorAll('.component-card').forEach(node=>node.remove());openAuthDialog()}applyWritePermissions();renderWebUsers()}
function applyWritePermissions(){document.querySelectorAll('.web-control button,.fixed-value-control button,#device-list button.danger,.modbus-server-control button,#error-log-dialog .dialog-actions button:first-child').forEach(button=>button.disabled=!authState.canWrite);const details=document.querySelector('#details-content button[type=submit]');if(details)details.hidden=!authState.canWrite}
function openAuthDialog(){if(authState.authenticated){logout();return}const setup=authState.enabled&&!authState.initialized,dialog=document.querySelector('#auth-dialog');document.querySelector('#auth-title').textContent=setup?'Create administrator':'Login';document.querySelector('#auth-help').textContent=setup?'Create the first administrator. Passwords require at least 10 characters.':'Enter your web interface account. Use HTTPS when connecting over a network.';document.querySelector('#auth-submit').textContent=setup?'Create administrator':'Login';document.querySelector('#auth-confirm-label').hidden=!setup;document.querySelector('#auth-password-confirm').required=setup;document.querySelector('#auth-password').autocomplete=setup?'new-password':'current-password';if(!dialog.open)dialog.showModal()}
function submitAuthentication(event){event.preventDefault();const username=document.querySelector('#auth-username').value.trim(),password=document.querySelector('#auth-password').value;if(!authState.initialized&&password!==document.querySelector('#auth-password-confirm').value){showToast('Passwords do not match',true);return}send((authState.initialized?'authLogin:':'authInitialize:')+JSON.stringify({username,password}));document.querySelector('#auth-password').value='';document.querySelector('#auth-password-confirm').value=''}
function logout(){send('authLogout');automationStarted=false;clearInterval(timer)}
function openUserAdminDialog(){if(!authState.admin)return;document.querySelector('#anonymous-view').checked=authState.anonymousView;renderWebUsers();const dialog=document.querySelector('#user-admin-dialog');if(!dialog.open)dialog.showModal();send('authAdmin:'+JSON.stringify({action:'list'}))}
function renderWebUsers(){const list=document.querySelector('#web-user-list');if(!list)return;list.replaceChildren();managedUsers.forEach(user=>{const row=document.createElement('div'),description=document.createElement('span'),remove=document.createElement('button');row.className='web-user-row';description.textContent=user.username+' ';const roles=document.createElement('small');roles.textContent=user.admin?'administrator':user.write?'read + write':user.read?'view only':'no access';description.append(roles);description.onclick=()=>{document.querySelector('#web-user-name').value=user.username;document.querySelector('#web-user-read').checked=user.read;document.querySelector('#web-user-write').checked=user.write;document.querySelector('#web-user-admin').checked=user.admin};remove.type='button';remove.textContent='Delete';remove.disabled=user.username===authState.username;remove.onclick=()=>{if(confirm('Delete user '+user.username+'?'))send('authAdmin:'+JSON.stringify({action:'delete',username:user.username}))};row.append(description,remove);list.append(row)})}
function saveWebUser(event){event.preventDefault();const request={action:'save',username:document.querySelector('#web-user-name').value.trim(),password:document.querySelector('#web-user-password').value,read:document.querySelector('#web-user-read').checked,write:document.querySelector('#web-user-write').checked,admin:document.querySelector('#web-user-admin').checked};send('authAdmin:'+JSON.stringify(request));document.querySelector('#web-user-password').value=''}
function setAnonymousView(){send('authAdmin:'+JSON.stringify({action:'anonymousView',enabled:document.querySelector('#anonymous-view').checked}))}
window.addEventListener('resize',drawConnections);window.addEventListener('DOMContentLoaded',()=>{const size=parseInt(localStorage.getItem('automation-canvas-size')||'1400',10),canvas=document.querySelector('#component-canvas');canvas.dataset.size=size;canvas.style.width=size+'px';canvas.style.height=size+'px';updateCanvasSize()});
